  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary: Approves a pending IPO application. If the application is in PENDING status
   *          and the related customer is still eligible for IPO, the application status
   *          changes to APPROVAL, and two information emails are dispatched (one to the
   *          customer and one to the company). Returns true on success, false otherwise.
   * Algorithm:
   *   1. If status != PENDING, return false.
   *   2. If customer.isEligibleForIPO() == false, return false.
   *   3. Set status = APPROVAL.
   *   4. Build email content via Email.createEmailContent(company, share, customer, amountOfMoney).
   *   5. Create one Email for the customer (receiver = customer.email) and add to emails.
   *   6. Create one Email for the company (receiver = company.email) and add to emails.
   *   7. Return true.
   * Related Features: status, amountOfMoney, share, company, customer, emails
   * Related Classes: Customer, Company, Email, ApplicationStatus
   * Input: None (operates on internal state).
   * Output: boolean - true if the pending application was successfully approved and emails sent; false otherwise.
   * Pre-condition: The application exists and its current status is PENDING; the related customer is eligible for IPO.
   * Post-condition: On success, status is APPROVAL and two new Email objects are added to the emails list
   *                 (one addressed to the customer, one to the company). On failure, state is unchanged.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public boolean approve()
  {
    if (getStatus() != ApplicationStatus.PENDING)
    {
      return false;
    }
    if (!getCustomer().isEligibleForIPO())
    {
      return false;
    }
    setStatus(ApplicationStatus.APPROVAL);
    Email contentBuilder = IpoFactory.eINSTANCE.createEmail();
    String content = contentBuilder.createEmailContent(getCompany(), getShare(), getCustomer(), getAmountOfMoney());
    Email customerEmail = IpoFactory.eINSTANCE.createEmail();
    customerEmail.setContent(content);
    customerEmail.setReceiver(getCustomer().getEmail());
    getEmails().add(customerEmail);
    Email companyEmail = IpoFactory.eINSTANCE.createEmail();
    companyEmail.setContent(content);
    companyEmail.setReceiver(getCompany().getEmail());
    getEmails().add(companyEmail);
    return true;
  }

